import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"24、【復】 震下坤上","description":"橫渠易說 - 24、【復】 震下坤上","frontmatter":{"title":"24、【復】 震下坤上","description":"橫渠易說 - 24、【復】 震下坤上"},"headers":[],"relativePath":"classics/hengqu/026.md","filePath":"classics/hengqu/026.md"}'),l={name:"classics/hengqu/026.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_24、【復】-震下坤上" tabindex="-1">24、【復】 震下坤上 <a class="header-anchor" href="#_24、【復】-震下坤上" aria-label="Permalink to “24、【復】 震下坤上”">​</a></h1><p>靜之動也無休息之期，故地雷為卦，言反又言復，終則有始，循環無窮，入，指其化而裁之耳。深其反也，幾其復也，故曰“反覆其道”，又曰“出入無疾”。</p><h3 id="彖曰-復亨-剛反動而以順行-是以-出入無疾-朋來無咎-。-反覆其道-七日來複-天行也-利有攸往-剛長也。復其見天地之心乎" tabindex="-1">彖曰：復亨，剛反動而以順行，是以“出入無疾，朋來無咎”。“反覆其道，七日來複”，天行也；“利有攸往”，剛長也。復其見天地之心乎! <a class="header-anchor" href="#彖曰-復亨-剛反動而以順行-是以-出入無疾-朋來無咎-。-反覆其道-七日來複-天行也-利有攸往-剛長也。復其見天地之心乎" aria-label="Permalink to “彖曰：復亨，剛反動而以順行，是以“出入無疾，朋來無咎”。“反覆其道，七日來複”，天行也；“利有攸往”，剛長也。復其見天地之心乎!”">​</a></h3><p>復言“天地之心”，鹹、恆、大壯言“天地之情”。心，內也，其原在內時，則有形見，情則見於事也，故可得而名狀。自姤而剝，至於上九，其數六也。剝之與復，不可容線，須臾不復，則乾坤之道息也，故適盡即生，更無先後之次也。此義最大。臨卦“至於八月有兇”，此言“七日來複”，何也？剛長之時，豫戒以陰長之事，故言“至於八月有兇”；若復則不可須臾斷，故言“七日”。七日者，畫夜相繼，元無斷續之時也。大抵言“天地之心”者，天地之大德曰生，則以生物為本者，乃天地之心也。地雷見天地之心者，天地之心惟是生物，天地之大德曰生也。雷復於地中，卻是生物。彖曰：“終則有始，天行也。”天行何嘗有息？正以靜，有何期程？此動是靜中之動，靜中之動，動而不窮，又有甚首尾起滅？自有天地以來以迄於今，蓋為靜而動。天則無心無為，無所主宰，恆然如此，有何休歇？人之德性亦與此合，乃是己有，苟心中造作安排而靜，則安能久!然必從此去，蓋靜者進德之基也。</p><h3 id="象曰-雷在地中-復-先王以至日閉關-商旅不行-後不省方。" tabindex="-1">象曰：雷在地中，復，先王以至日閉關，商旅不行，後不省方。 <a class="header-anchor" href="#象曰-雷在地中-復-先王以至日閉關-商旅不行-後不省方。" aria-label="Permalink to “象曰：雷在地中，復，先王以至日閉關，商旅不行，後不省方。”">​</a></h3><p>凡言“後”者，大率謂繼體守成之主也。復言“先王以至日閉關，商旅不行，後不省方”，以此校之，則後為繼承之主明矣。“先王以至日閉關”者，先王所重於至日，以其順陰陽往來，“閉關”者，取其靜也，閉關則商旅不行。先王無放過事，順時以示法，亦以示民。“後不省方”，如言富庶優暇，不甚省事，又明是繼文之主。</p><h3 id="初九-不遠復-無只悔-元吉。-象曰-不遠之復-以修身也。" tabindex="-1">初九，不遠復，無只悔，元吉。 象曰：不遠之復，以修身也。 <a class="header-anchor" href="#初九-不遠復-無只悔-元吉。-象曰-不遠之復-以修身也。" aria-label="Permalink to “初九，不遠復，無只悔，元吉。 象曰：不遠之復，以修身也。”">​</a></h3><p>祗猶承也，受也。一雲：祗悔作神祗之祗。祗之為義，示也，效也，見也，言悔可使亡，不可使成而形也。</p><h3 id="六二-休復-吉。-象曰-休復之吉-以下仁也。" tabindex="-1">六二，休復，吉。 象曰：休復之吉，以下仁也。 <a class="header-anchor" href="#六二-休復-吉。-象曰-休復之吉-以下仁也。" aria-label="Permalink to “六二，休復，吉。 象曰：休復之吉，以下仁也。”">​</a></h3><p>下比於陽，故樂行其善。</p><h3 id="六三-頻復-厲無咎。-象曰-頻復之厲-義無咎也-。" tabindex="-1">六三，頻復，厲無咎。 象曰：頻復之厲，義無咎也”。 <a class="header-anchor" href="#六三-頻復-厲無咎。-象曰-頻復之厲-義無咎也-。" aria-label="Permalink to “六三，頻復，厲無咎。 象曰：頻復之厲，義無咎也”。”">​</a></h3><p>所處非位，非頻蹙自危，不能無吝。吝一作咎。</p><h3 id="六四-中行獨復。-象曰-中行獨復-以從道也。" tabindex="-1">六四，中行獨復。 象曰：“中行獨復”，以從道也。 <a class="header-anchor" href="#六四-中行獨復。-象曰-中行獨復-以從道也。" aria-label="Permalink to “六四，中行獨復。 象曰：“中行獨復”，以從道也。”">​</a></h3><p>柔危之世，以中道合正應，故不與群爻同。</p><h3 id="六五-敦復-無悔。-象曰-敦復無悔-中以自考也。" tabindex="-1">六五，敦復，無悔。 象曰：“敦復無悔”，中以自考也。 <a class="header-anchor" href="#六五-敦復-無悔。-象曰-敦復無悔-中以自考也。" aria-label="Permalink to “六五，敦復，無悔。 象曰：“敦復無悔”，中以自考也。”">​</a></h3><p>性順位中，無它應援，以敦實自求而已。剛長柔危之世，能以中道自考，故可無悔，不然，取悔必矣。</p><h3 id="上六-迷復-兇-有災眚。用行師-終有大敗-以其國君兇-至於十年不克徵。-象曰-迷復之兇-反君道也。" tabindex="-1">上六，迷復，兇，有災眚。用行師，終有大敗，以其國君兇，至於十年不克徵。 象曰：迷復之兇，反君道也。 <a class="header-anchor" href="#上六-迷復-兇-有災眚。用行師-終有大敗-以其國君兇-至於十年不克徵。-象曰-迷復之兇-反君道也。" aria-label="Permalink to “上六，迷復，兇，有災眚。用行師，終有大敗，以其國君兇，至於十年不克徵。 象曰：迷復之兇，反君道也。”">​</a></h3><p>君道過亢反常，無施而可，故天災人害，師敗君兇，久衰而不可振也。</p>',18)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
